from solution import greatest_common_divisor
import math
import pytest
from hypothesis import given
import hypothesis.strategies as st


def test_examples_from_spec():
    assert greatest_common_divisor(3, 5) == 1
    assert greatest_common_divisor(25, 15) == 5


def test_zero_first_arg_is_second():
    assert greatest_common_divisor(0, 5) == 5
    assert greatest_common_divisor(0, 1) == 1
    assert greatest_common_divisor(0, 25) == 25


def test_zero_second_arg_is_first():
    assert greatest_common_divisor(5, 0) == 5
    assert greatest_common_divisor(15, 0) == 15
    assert greatest_common_divisor(1, 0) == 1


def test_zero_zero_is_zero():
    assert greatest_common_divisor(0, 0) == 0


def test_negative_inputs_do_not_raise():
    assert greatest_common_divisor(-25, 15) == 5
    assert greatest_common_divisor(25, -15) == 5
    assert greatest_common_divisor(-25, -15) == 5
    assert greatest_common_divisor(-3, 5) == 1
    assert greatest_common_divisor(-7, -7) == 7


def test_result_nonnegative():
    assert greatest_common_divisor(-10, 6) >= 0
    assert greatest_common_divisor(10, 6) >= 0


@given(st.integers(min_value=-50, max_value=50), st.integers(min_value=-50, max_value=50))
def test_property_matches_math_gcd_reference(a, b):
    assert greatest_common_divisor(a, b) == math.gcd(a, b)


@given(st.integers(min_value=-50, max_value=50), st.integers(min_value=-50, max_value=50))
def test_property_result_divides_both_inputs(a, b):
    g = greatest_common_divisor(a, b)
    if a == 0 and b == 0:
        assert g == 0
    else:
        assert g > 0
        assert a % g == 0
        assert b % g == 0


@given(st.integers(min_value=-50, max_value=50), st.integers(min_value=-50, max_value=50))
def test_property_symmetry(a, b):
    assert greatest_common_divisor(a, b) == greatest_common_divisor(b, a)


@given(st.integers(min_value=-50, max_value=50))
def test_property_same_number(a):
    assert greatest_common_divisor(a, a) == abs(a)


@given(st.integers(min_value=-50, max_value=50), st.integers(min_value=-50, max_value=50))
def test_property_sign_invariance(a, b):
    assert greatest_common_divisor(a, b) == greatest_common_divisor(abs(a), abs(b))


@given(
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=1, max_value=10),
)
def test_property_common_divisor_is_not_greater(a, b, d):
    # Any common divisor cannot exceed the gcd (for non-zero pair).
    g = greatest_common_divisor(a, b)
    if a == 0 and b == 0:
        return
    if d != 0 and a % d == 0 and b % d == 0:
        assert abs(d) <= g
